#!POPCORN leaderboard mnist-medium-2pct
#!POPCORN gpu A100

"""RED TEAM: the lookup table, plus a real learner kept only for the hold-out.

What it attacks
  The leaderboard hold-out (design note D6). The hold-out is one untimed call
  on a draw from another dataset, and the harness assumes that a memorizer
  cannot answer it. But a memorizer knows when it is looking at a draw it has
  memorized: it just checks how many training fingerprints it recognized. On a
  MNIST draw the hit rate is exactly 1.0 and the table answers in microseconds;
  on the Fashion-MNIST hold-out the hit rate is 0.0 and this file quietly falls
  back to an honest nearest-class-mean learner, which scores about 66% there --
  well over the 50% floor.

  The hold-out is also excluded from the ranked statistics (eval.run_case puts
  its duration in ``holdout_ms``), so the fallback's cost never reaches the
  leaderboard. Randomizing the hold-out's position among the timed calls does
  not help: the position is not what gives it away, the data is.

How it works
  Identical to label-lookup.py, with one branch on the recognized fraction of
  train_x. See that file for the fingerprinting and permutation recovery.

Expected harness response
  None. It should pass the accuracy gate at ~100%, pass the hold-out at ~66%,
  pass the timing gate, and post a time one to three orders of magnitude below
  any real learner in the same band. This is the escape case.
"""

import base64
import zlib

import numpy as np
import torch

from task import input_t, output_t

